import type { Transaction } from './types';
import { totalsByType, type TypeTotals } from './transactionTypes';

/** Same limits as the server: ids per request and characters of the notes. */
export const BULK_MAX = 500;
export const NOTES_MAX = 1000;

export interface SelectionFacts {
  totals: TypeTotals;
  /** First and last date (YYYY-MM-DD) of the selected movements. */
  first: string;
  last: string;
  /** Generated by a recurring rule. */
  recurring: number;
  savings: number;
}

export function selectionFacts(items: Transaction[]): SelectionFacts {
  const dates = items.map((tx) => tx.date.slice(0, 10)).sort();
  return {
    totals: totalsByType(items),
    // Only used with at least one movement selected.
    first: dates[0],
    last: dates[dates.length - 1],
    recurring: items.filter((tx) => tx.recurringRuleId).length,
    savings: items.filter((tx) => tx.type === 'SAVING').length,
  };
}

/** The notes a movement would end up with (the server joins appended text with a space). */
export function notesAfter(
  current: string | null,
  text: string,
  mode: 'replace' | 'append'
): string | null {
  const clean = text.trim();
  if (mode === 'append' && current) return clean ? `${current} ${clean}` : current;
  return clean || null;
}

/** Splits the selection into the movements the new notes fit in and the ones they would not. */
export function splitByNotesLength(
  items: Transaction[],
  text: string,
  mode: 'replace' | 'append'
): { valid: Transaction[]; tooLong: Transaction[] } {
  const valid: Transaction[] = [];
  const tooLong: Transaction[] = [];
  for (const tx of items) {
    const next = notesAfter(tx.notes, text, mode);
    (next !== null && next.length > NOTES_MAX ? tooLong : valid).push(tx);
  }
  return { valid, tooLong };
}
